    public static function maybeUpgrade():bool{
        if((string)get_option('eh7_schema_version','')===self::VERSION){delete_option('eh7_schema_migration_error');return true;}
        try{self::install();delete_option('eh7_schema_migration_error');return true;}
        catch(\Throwable $e){$msg=substr($e->getMessage(),0,1000);update_option('eh7_schema_migration_error',$msg,false);error_log('EH7 schema migration failed: '.$msg);return false;}
    }
    public static function install():void{
        require_once ABSPATH.'wp-admin/includes/upgrade.php';
        $db=Db::wpdb();
        $charset=$db->get_charset_collate();
        foreach(self::definitions() as $name=>$body){
            dbDelta('CREATE TABLE '.Db::table($name).' ('.$body.') '.$charset.';');
        }
        foreach(array_keys(self::definitions()) as $name){
            $table=Db::table($name);
            $exists=(string)$db->get_var($db->prepare('SHOW TABLES LIKE %s',$table));
            if($exists!==$table)throw new \RuntimeException('ERP schema migration failed: missing table '.$table);
        }
        // dbDelta can fail to add a nullable column to some pre-existing tables.
        // Keep this migration explicit and idempotent so upgrades from clean-11 are reliable.
        self::ensureColumn('idempotency_keys','payload_hash','CHAR(64) NULL AFTER operation');
        self::ensureColumn('mobile_sessions','device_key','CHAR(64) NULL AFTER device_name');
        self::ensureColumn('employees','reporting_designation_code','VARCHAR(40) NULL AFTER designation_code');
        self::ensureColumn('daily_issue_lines','ho_amount_snapshot','DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER sale_price_snapshot');
        self::ensureColumn('daily_issue_lines','bm_profit_snapshot','DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER ho_amount_snapshot');
        self::ensureColumn('daily_issue_lines','office_expense_snapshot','DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER bm_profit_snapshot');
        self::ensureColumn('evening_lines','ho_amount','DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER total_amount');
        self::ensureColumn('evening_lines','bm_profit','DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER ho_amount');
        self::ensureColumn('evening_lines','office_expense','DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER bm_profit');
        self::ensureInterBranchClearingAccounts();
        $idem=Db::table('idempotency_keys');
        $payload=(string)$db->get_var("SHOW COLUMNS FROM {$idem} LIKE 'payload_hash'");
        if($payload!=='payload_hash')throw new \RuntimeException('ERP schema migration failed: idempotency payload_hash missing.');
        self::backfillEmployeeBranchHistory();
        self::ensureColumn('employee_documents','private_file_id','BIGINT UNSIGNED NULL');
        self::ensureColumn('hr_candidate_documents','private_file_id','BIGINT UNSIGNED NULL');
        self::ensureColumn('payroll_items','calculation_json','LONGTEXT NULL');
        self::ensureColumn('payroll_runs','calculation_version','VARCHAR(30) NULL');
        self::ensureColumn('attendance','checkout_exception','TINYINT(1) NOT NULL DEFAULT 0 AFTER check_out_lng');
        self::ensureColumn('attendance','checkout_exception_reason','VARCHAR(255) NULL AFTER checkout_exception');
        self::ensureColumn('attendance','checkout_exception_by','BIGINT UNSIGNED NULL AFTER checkout_exception_reason');
        self::ensureColumn('attendance','checkout_exception_at','DATETIME NULL AFTER checkout_exception_by');
        self::ensureColumn('stock_quarantine','unit_cost_snapshot','DECIMAL(14,4) NOT NULL DEFAULT 0 AFTER quantity');
        self::ensureColumn('stock_quarantine','journal_entry_id','BIGINT UNSIGNED NULL AFTER resolved_by');

        // Hot-path indexes for large-data UAT/production readiness.
        self::ensureIndex('employees','branch_status','company_id,assigned_branch_id,status');
        self::ensureIndex('parties','branch_type_status','company_id,branch_id,type,status');
        self::ensureIndex('suppliers','company_status','company_id,status');
        self::ensureIndex('counter_sales','branch_date','company_id,branch_id,sale_date,id');
        self::ensureIndex('counter_sales','branch_status_outstanding','company_id,branch_id,status,outstanding_amount');
        self::ensureIndex('purchase_bills','branch_status_outstanding','company_id,branch_id,status,outstanding_amount,bill_date,id');
        self::ensureIndex('stock_transfers','source_status','company_id,source_branch_id,status,id');
        self::ensureIndex('stock_transfers','destination_status','company_id,destination_branch_id,status,id');
        self::ensureIndex('stock_adjustments','branch_status','company_id,branch_id,status,id');
        self::ensureIndex('journal_entries','company_status_date','company_id,status,entry_date,id');
        self::ensureIndex('journal_entries','company_source','company_id,source_type,source_id,status');
        self::ensureIndex('tasks','employee_status_due','company_id,assigned_employee_id,status,due_at,id');
        self::ensureIndex('notifications','employee_created','company_id,employee_id,created_at,id');
        self::ensureIndex('holidays','scope_date','company_id,branch_id,holiday_date,active');
        self::ensureIndex('announcements','company_status_published','company_id,status,published_at,id');

        $salaryTable=Db::table('salary_revisions');$employeeTable=Db::table('employees');
        Db::mustQuery($db,$db->prepare("INSERT INTO {$salaryTable} (company_id,employee_id,effective_from,monthly_salary,status,reason,created_at) SELECT e.company_id,e.id,GREATEST(COALESCE(e.joining_date,%s),%s),e.monthly_salary,'baseline','Upgrade snapshot; earlier salary must be independently confirmed',%s FROM {$employeeTable} e WHERE NOT EXISTS(SELECT 1 FROM {$salaryTable} s WHERE s.company_id=e.company_id AND s.employee_id=e.id)",Db::today(),Db::today(),Db::now()));
        \ExcelHerbal\ERP7\Organization\DocumentVault::provisionKey();
        update_option('eh7_schema_version',self::VERSION,false);
    }
    private static function backfillEmployeeBranchHistory():void{
        $db=Db::wpdb();$employees=Db::table('employees');$history=Db::table('employee_branch_history');
        $rows=(array)$db->get_results("SELECT e.id,e.company_id,e.assigned_branch_id,e.joining_date,e.created_at FROM {$employees} e WHERE e.status='active' AND NOT EXISTS(SELECT 1 FROM {$history} h WHERE h.company_id=e.company_id AND h.employee_id=e.id AND h.effective_to IS NULL) ORDER BY e.id",ARRAY_A);
        foreach($rows as $e){
            $company=(int)$e['company_id'];$employee=(int)$e['id'];$branch=(int)$e['assigned_branch_id'];
            if($company<1||$employee<1||$branch<1)continue;
            $from=trim((string)($e['joining_date']??''));if($from==='')$from=substr((string)($e['created_at']??''),0,10);if($from==='')$from=Db::today();
            $changer=(int)$db->get_var($db->prepare("SELECT id FROM {$employees} WHERE company_id=%d AND status='active' AND UPPER(designation_code) IN ('SYSADMIN','SYSTEM_ADMIN','ADMIN','ADMINISTRATOR') ORDER BY id LIMIT 1",$company));
            if($changer<1)$changer=$employee;
            Db::mustInsert($db,$history,['company_id'=>$company,'employee_id'=>$employee,'branch_id'=>$branch,'effective_from'=>$from,'effective_to'=>null,'reason'=>'System backfill: current branch assignment','changed_by'=>$changer,'created_at'=>Db::now()]);
        }
    }


    private static function ensureInterBranchClearingAccounts():void{
        $db=Db::wpdb();$companies=Db::table('companies');$accounts=Db::table('accounts');
        $ids=(array)$db->get_col("SELECT id FROM {$companies} WHERE status='active' ORDER BY id");
        foreach($ids as$id){
            $companyId=(int)$id;if($companyId<1)continue;
            $row=$db->get_row($db->prepare("SELECT id,active FROM {$accounts} WHERE company_id=%d AND code='INTER_BRANCH_CLEARING' LIMIT 1",$companyId),ARRAY_A);
            if(!$row){Db::mustInsert($db,$accounts,['company_id'=>$companyId,'code'=>'INTER_BRANCH_CLEARING','name'=>'Inter-branch Transfer Clearing','type'=>'asset','subtype'=>'inter_branch_clearing','active'=>1]);continue;}
            if((int)$row['active']!==1)Db::mustUpdate($db,$accounts,['active'=>1],['id'=>(int)$row['id']]);
        }
    }

    private static function ensureIndex(string $tableName,string $indexName,string $columns):void{
        if(!preg_match('/^[A-Za-z0-9_]+$/',$indexName)||!preg_match('/^[A-Za-z0-9_,]+$/',$columns)){
            throw new \LogicException('Unsafe internal schema index definition.');
        }
        $db=Db::wpdb();$table=Db::table($tableName);
        $existing=(int)$db->get_var($db->prepare(
            "SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name=%s AND index_name=%s",
            $table,$indexName
        ));
        if($existing>0)return;
        $result=$db->query("ALTER TABLE {$table} ADD INDEX {$indexName} ({$columns})");
        if($result===false){
            $error=trim((string)($db->last_error??''));
            throw new \RuntimeException('ERP schema migration failed adding index '.$tableName.'.'.$indexName.($error!==''?': '.$error:''));
        }
    }

    private static function ensureColumn(string $tableName,string $column,string $definition):void{
        $db=Db::wpdb();
        $table=Db::table($tableName);
        $existing=(string)$db->get_var($db->prepare("SHOW COLUMNS FROM {$table} LIKE %s",$column));
        if($existing===$column)return;
        // table/column/definition are internal constants supplied by Schema, never request data.
        $result=$db->query("ALTER TABLE {$table} ADD COLUMN {$column} {$definition}");
        if($result===false){
            $error=trim((string)($db->last_error??''));
            throw new \RuntimeException('ERP schema migration failed adding '.$tableName.'.'.$column.($error!==''?': '.$error:''));
        }
    }
